arguments.command:
python3 -c "
import sys; sys.path.insert(0, '.')
import parse
# Test various formats
try:
    p = parse.Parser('{a}b')
    print('OK: {a}b')
except Exception as e:
    print(f'Error: {e}')

try:
    p = parse.Parser('a{a}')
    print('OK: a{a}')
except Exception as e:
    print(f'Error: {e}')

try:
    p = parse.Parser('{a}{b}')
    print('OK: {a}{b}')
except Exception as e:
    print(f'Error: {e}')

try:
    p = parse.Parser('{{a}}')
    print('OK: {{a}}')
except Exception as e:
    print(f'Error: {e}')

try:
    p = parse.Parser('{a b}')
    print('OK: {a b}')
except Exception as e:
    print(f'Error: {e}')
"
